<!doctype html><html><head><meta charset="utf-8"><style>body{font:12px DejaVu Sans,sans-serif;color:#17211b}h1,h2{color:#14532d}table{width:100%;border-collapse:collapse;margin:10px 0 20px}th,td{border:1px solid #cbd5d1;padding:6px;text-align:left}th{background:#f0fdf4}.muted{color:#64748b}</style></head><body><h1><?= esc($centerName??'Barangay ChildCare') ?></h1><p class="muted">Child Health Record · Printed <?= esc(date('F j, Y')) ?></p><h2><?= esc($child['first_name'].' '.($child['middle_name']??'').' '.$child['last_name']) ?></h2><p>Child ID: <?= esc($child['child_code']??'Pending') ?> · Birthdate: <?= esc(format_date($child['birthdate'])) ?> · Sex: <?= esc(ucfirst($child['sex'])) ?> · Purok: <?= esc($child['purok_name']??'') ?></p><h2>Growth records</h2><table><thead><tr><th>Date</th><th>Weight</th><th>Height</th><th>Status</th></tr></thead><tbody><?php foreach($child['growth_records'] as $r): ?><tr><td><?= esc(format_date($r['visit_date'])) ?></td><td><?= esc($r['weight_kg']) ?> kg</td><td><?= esc($r['height_cm']) ?> cm</td><td><?= esc($r['nutrition_status']) ?></td></tr><?php endforeach ?></tbody></table><h2>Medical history / check-ups</h2><table><thead><tr><th>Date</th><th>Complaint</th><th>Findings / diagnosis</th><th>Treatment</th><th>Follow-up</th></tr></thead><tbody><?php foreach(($child['checkups']??[]) as $r): ?><tr><td><?= esc(format_date($r['checkup_date'])) ?></td><td><?= esc($r['chief_complaint']??'—') ?></td><td><?= esc(trim(($r['findings']??'').' '.($r['diagnosis']??''))) ?></td><td><?= esc($r['treatment']??'—') ?></td><td><?= esc($r['follow_up_date']?format_date($r['follow_up_date']):'—') ?></td></tr><?php endforeach ?></tbody></table><h2>Immunization records</h2><table><thead><tr><th>Vaccine</th><th>Dose</th><th>Status</th><th>Date administered / due</th></tr></thead><tbody><?php foreach($child['doses'] as $d): ?><tr><td><?= esc($d['vaccine']) ?></td><td><?= esc($d['code']) ?></td><td><?= esc($d['status']) ?></td><td><?= esc(format_date($d['date_administered']??$d['due_date'])) ?></td></tr><?php endforeach ?></tbody></table><p class="muted">This document contains sensitive personal information. Share it only with authorized care providers.</p></body></html>
